import {expect, it, jest} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

// specs/hal-engine-config-hooks/spec.md#7
it('passes the session and beforeSession error to onError', async () => {
  const error = new Error('setup failed');
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const onError = jest.fn(async (_session: ChatSession, _error: Error) => {});
  const provider: AIProvider = {
    async *sendMessage() {},
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({baseSystemPrompt: 'HAL'}), undefined, {
    hooks: {
      beforeSession: async () => { throw error; },
      onError,
    },
  });

  await expect(orchestrator.processMessage(session)).rejects.toBe(error);
  expect(onError).toHaveBeenCalledWith(session, error);
});
EOF
